import { expect, test } from "../../fixtures";

test.describe("sign in", () => {
  test("requests without a session are rejected with not_authenticated", { tag: "@AUTH-05" }, async ({ request }) => {
    // Act
    const response = await request.get("/api/me");

    // Assert
    const body = await response.text();
    expect(response.status(), body).toBe(401);
    expect((JSON.parse(body) as { error: { code: string } }).error.code, body).toBe("not_authenticated");
  });
});
